using System;

class Player
{
    public string Name { get; }              // только чтение
    public int Hp { get; private set; }       // читать всем, менять - только внутри

    public Player(string name, int hp)
    {
        Name = name;
        Hp = hp;
    }

    public void TakeDamage(int dmg)
    {
        Hp = Math.Max(0, Hp - dmg);           // не уходим в минус
    }
}

class Program
{
    static void Main()
    {
        var hero = new Player("Азиз", 100);   // var = тип выводится сам
        hero.TakeDamage(30);
        Console.WriteLine($"{hero.Name}: {hero.Hp} HP");
    }
}

