using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        var nums = new List<int> { 4, 25, 8, 42, 15 };

        var result = nums
            .Where(n => n > 10)              // WHERE n > 10
            .OrderByDescending(n => n);      // ORDER BY n DESC

        foreach (var n in result)
            Console.WriteLine(n);            // 42, 25, 15
    }
}

